(()=>{'use strict';if(window.__qpuSideList)return;window.__qpuSideList=true;let loading=false;const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:[];async function populate(){const root=document.querySelector('.am-split[data-am-screen="purchase"]');if(!root||root.dataset.qpuListReady||loading)return;loading=true;try{const res=await fetch('/api/purchase-orders',{credentials:'include',cache:'no-store'}),payload=await res.json();if(!res.ok||payload.success===false)throw Error(payload.message||'조회 실패');if(!root.isConnected)return;const data=rows(payload),list=root.querySelector('.am-list-items'),title=root.querySelector('.am-list-title span'),count=root.querySelector('.am-list-count'),search=root.querySelector('.am-list-search');if(!list)return;root.dataset.qpuListReady='1';if(title)title.textContent=data.length+'건';if(count)count.textContent=data.length+'건 구매발주';list.replaceChildren();const btns=[];data.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.className='am-list-item';const t=document.createElement('b');t.textContent=p.purchaseNo||p.no||'발주 '+(i+1);const sub=document.createElement('span');sub.textContent=[p.supplier,p.item||p.material].filter(Boolean).join(' · ');b.append(t,sub);b.addEventListener('click',()=>{btns.forEach(x=>x.classList.toggle('active',x===b));const note=root.querySelector('.am-detail-note');if(note)note.textContent='선택한 구매발주: '+t.textContent;root.querySelector('#qpu-selected-record')?.remove();const panel=root.querySelector('.am-detail-note')?.closest('section')||root;const candidates=[...root.querySelectorAll('input,select,textarea')].filter(el=>!el.closest('.am-list-items,.am-list-search,.qpu-side-pagination'));const field=(word,type)=>candidates.find(el=>{const label=el.closest('tr')?.querySelector('th,td:first-child')?.textContent||el.closest('label')?.textContent||el.parentElement?.previousElementSibling?.textContent||'';return label.includes(word)&&(type?el.tagName.toLowerCase()===type:true)});const set=(el,value)=>{if(!el)return;el.value=String(value??'');el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};const map=[['발주일자',p.orderDate||p.order_date],['발주일',p.orderDate||p.order_date],['공급업체',p.supplier||p.vendor],['품목명',p.item||p.material],['수량',p.qty??p.quantity],['요청입고',p.requestedDueDate||p.due||p.receiptDate],['발주상태',p.status||p.approvalStatus],['비고',p.notes||'']];map.forEach(([label,value])=>{const el=field(label);if(el)set(el,value)});const title=root.querySelector('.am-detail-note');if(title)title.textContent='선택한 기존 발주: '+t.textContent+' (조회 전용 · 저장하지 않음)';});list.append(b);btns.push(b)});let page=1;const pager=document.createElement('div');pager.className='qpu-side-pagination';pager.style.cssText='display:flex;justify-content:center;gap:5px;padding:8px';list.after(pager);function draw(){const q=(search?.value||'').trim().toLowerCase(),matched=btns.filter(b=>b.textContent.toLowerCase().includes(q)),total=Math.max(1,Math.ceil(matched.length/10));page=Math.min(page,total);btns.forEach(b=>{b.hidden=true;b.style.display='none'});matched.slice((page-1)*10,page*10).forEach(b=>{b.hidden=false;b.style.display='flex'});pager.replaceChildren();for(let i=1;i<=total;i++){const b=document.createElement('button');b.type='button';b.textContent=i;b.style.cssText='padding:4px 8px;border:1px solid #d1dce8;border-radius:4px;background:'+(i===page?'#2d73db;color:white':'white');b.onclick=()=>{page=i;draw()};pager.append(b)}}search?.addEventListener('input',()=>{page=1;draw()});draw()}catch(e){const list=root.querySelector('.am-list-items');if(list)list.textContent='기존 발주 목록 조회 실패: '+e.message}finally{loading=false}}new MutationObserver(()=>{if(document.querySelector('.am-split[data-am-screen="purchase"]:not([data-qpu-list-ready])'))populate()}).observe(document.body,{childList:true,subtree:true});populate()})();